-- Run once in the Supabase SQL editor after deploying the updated app.
-- This merges only the named account; rerunning does not duplicate exercises.
begin;
do $import$
declare
  target_id uuid;
  saved jsonb;
  week jsonb;
  entry record;
  exercise jsonb;
  items jsonb;
  incoming jsonb := $plan${"monday":[{"name":"Dip machine","prescription":"4×12–20","session":"","dayTitle":"Push + intervals","notes":"","sets":"","reps":"","weight":""}],"tuesday":[{"name":"Dead bug","prescription":"2×10 per side","session":"","dayTitle":"","notes":"","sets":"","reps":"","weight":""},{"name":"Farmer carry","prescription":"4×40 seconds at 40 lb each","session":"","dayTitle":"","notes":"","sets":"","reps":"","weight":""}],"wednesday":[{"name":"Front plank","prescription":"3×45–60 seconds","session":"Before work · 40 minutes","dayTitle":"YMCA legs","notes":"","sets":"","reps":"","weight":""},{"name":"Bird dog","prescription":"2×10 per side","session":"Before work · 40 minutes","dayTitle":"YMCA legs","notes":"","sets":"","reps":"","weight":""},{"name":"Leg press","prescription":"4×8–12 at 190–210 lb","session":"After work · 60 minutes","dayTitle":"YMCA legs","notes":"","sets":"","reps":"","weight":""},{"name":"Seated leg curl","prescription":"3×10–15 at 75–85 lb","session":"After work · 60 minutes","dayTitle":"YMCA legs","notes":"","sets":"","reps":"","weight":""},{"name":"Leg extension","prescription":"3×10–15 at 65–75 lb","session":"After work · 60 minutes","dayTitle":"YMCA legs","notes":"","sets":"","reps":"","weight":""},{"name":"Hip abductor","prescription":"3×15–20 at 85–95 lb","session":"After work · 60 minutes","dayTitle":"YMCA legs","notes":"","sets":"","reps":"","weight":""},{"name":"Calf raise","prescription":"3×15–20","session":"After work · 60 minutes","dayTitle":"YMCA legs","notes":"","sets":"","reps":"","weight":""}],"thursday":[{"name":"Easy warm-up","prescription":"5 minutes","session":"Before work · 40 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Tempo intervals","prescription":"3 rounds of 6 minutes comfortably hard, 2 minutes easy","session":"Before work · 40 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Cool-down","prescription":"5 minutes","session":"Before work · 40 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Bicycle crunch","prescription":"3×20 total","session":"Before work · 40 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Side plank","prescription":"2×40 seconds per side","session":"Before work · 40 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Pull-ups","prescription":"4×6–10","session":"After work · 60 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Dumbbell floor press","prescription":"4×10–12 at 35 lb each","session":"After work · 60 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"One-arm dumbbell row","prescription":"3×12 per side at 40 lb","session":"After work · 60 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Dip machine","prescription":"3×12–15","session":"After work · 60 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Dumbbell shoulder press","prescription":"3×10 at 30–35 lb each","session":"After work · 60 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""},{"name":"Push-ups","prescription":"2×15–20","session":"After work · 60 minutes","dayTitle":"Upper body + tempo cardio","notes":"","sets":"","reps":"","weight":""}],"friday":[{"name":"Easy incline walk or light jog","prescription":"22–25 minutes","session":"Before work · 30 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""},{"name":"Reverse crunch","prescription":"2×15","session":"Before work · 30 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""},{"name":"Dead bug","prescription":"2×10 per side","session":"Before work · 30 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""},{"name":"Goblet split squat","prescription":"3×10 per leg at 35 lb","session":"After work · 40 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""},{"name":"Dumbbell glute bridge","prescription":"3×15 at 40 lb","session":"After work · 40 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""},{"name":"Bodyweight lateral lunge","prescription":"2×10 per side","session":"After work · 40 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""},{"name":"Standing calf raise","prescription":"3×20","session":"After work · 40 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""},{"name":"Hip and ankle mobility","prescription":"5–8 minutes","session":"After work · 40 minutes","dayTitle":"Shorter lower-body day","notes":"","sets":"","reps":"","weight":""}],"saturday":[{"name":"Steady run or incline walk","prescription":"23–25 minutes","session":"Morning · 30 minutes","dayTitle":"Full-body circuit","notes":"","sets":"","reps":"","weight":""},{"name":"Hanging knee raise","prescription":"2×12","session":"Morning · 30 minutes","dayTitle":"Full-body circuit","notes":"","sets":"","reps":"","weight":""},{"name":"Hollow hold","prescription":"2×25–35 seconds","session":"Morning · 30 minutes","dayTitle":"Full-body circuit","notes":"","sets":"","reps":"","weight":""},{"name":"Warm up for","prescription":"5 minutes","session":"Evening · 45 minutes","dayTitle":"Full-body circuit","notes":"","sets":"","reps":"","weight":""},{"name":"Pull-ups","prescription":"5–8","session":"Evening · 45 minutes","dayTitle":"Full-body circuit","notes":"Complete 4 rounds","sets":"","reps":"","weight":""},{"name":"Push-ups","prescription":"15–20","session":"Evening · 45 minutes","dayTitle":"Full-body circuit","notes":"Complete 4 rounds","sets":"","reps":"","weight":""},{"name":"Dip machine","prescription":"12–15","session":"Evening · 45 minutes","dayTitle":"Full-body circuit","notes":"Complete 4 rounds","sets":"","reps":"","weight":""},{"name":"Reverse lunges","prescription":"10 per leg","session":"Evening · 45 minutes","dayTitle":"Full-body circuit","notes":"Complete 4 rounds","sets":"","reps":"","weight":""},{"name":"Dumbbell row","prescription":"12 per side at 40 lb","session":"Evening · 45 minutes","dayTitle":"Full-body circuit","notes":"Complete 4 rounds\nRest 90 seconds between rounds\nFinish with 5 minutes of mobility","sets":"","reps":"","weight":""}],"sunday":[{"name":"Relaxed walk","prescription":"20–25 minutes","session":"Morning · 25–30 minutes","dayTitle":"Active recovery","notes":"","sets":"","reps":"","weight":""},{"name":"Dead bug","prescription":"1–2×10 per side","session":"Morning · 25–30 minutes","dayTitle":"Active recovery","notes":"","sets":"","reps":"","weight":""},{"name":"Side plank","prescription":"1×30 seconds per side","session":"Morning · 25–30 minutes","dayTitle":"Active recovery","notes":"","sets":"","reps":"","weight":""},{"name":"Easy stretching or a relaxed walk","prescription":"Easy stretching or a relaxed walk","session":"Evening · 20 minutes","dayTitle":"Active recovery","notes":"Focus on hips, calves, upper back, and shoulders","sets":"","reps":"","weight":""}]}$plan$::jsonb;
begin
  select id into strict target_id from auth.users where lower(email) = 'andrewpitman45@gmail.com';
  select data into strict saved from public.member_profiles where user_id = target_id for update;
  week := coalesce(saved->'weeklyWorkouts', '{}'::jsonb);
  for entry in select * from jsonb_each(incoming) loop
    items := coalesce(week->entry.key, '[]'::jsonb);
    for exercise in select * from jsonb_array_elements(entry.value) loop
      if not exists (select 1 from jsonb_array_elements(items) item
        where item->>'name' = exercise->>'name'
          and coalesce(item->>'session', '') = coalesce(exercise->>'session', '')) then
        items := items || jsonb_build_array(exercise);
      end if;
    end loop;
    week := jsonb_set(week, array[entry.key], items, true);
  end loop;
  update public.member_profiles set data = jsonb_set(saved, '{weeklyWorkouts}', week, true) || '{"workoutResetVersion":2}'::jsonb
    where user_id = target_id;
end
$import$;
commit;
